import{_ as o,o as t,c as a,a2 as s}from"./chunks/framework.om2R87yU.js";const h=JSON.parse('{"title":"Important Notes","description":"","frontmatter":{},"headers":[],"relativePath":"bull/important-notes.md","filePath":"bull/important-notes.md","lastUpdated":1634460717000}'),r={name:"bull/important-notes.md"};function n(l,e,i,c,d,p){return t(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="important-notes" tabindex="-1">Important Notes <a class="header-anchor" href="#important-notes" aria-label="Permalink to &quot;Important Notes&quot;">​</a></h1><p>The queue aims for an &quot;at least once&quot; working strategy. This means that in some situations, a job could be processed more than once. This mostly happens when a worker fails to keep a lock for a given job during the total duration of the processing.</p><p>When a worker is processing a job it will keep the job &quot;locked&quot; so other workers can&#39;t process it.</p><p>It&#39;s important to understand how locking works to prevent your jobs from losing their lock - becoming <em>stalled</em> - and being restarted as a result. Locking is implemented internally by creating a lock for <code>lockDuration</code> on interval <code>lockRenewTime</code> (which is usually half <code>lockDuration</code>). If <code>lockDuration</code> elapses before the lock can be renewed, the job will be considered stalled and is automatically restarted; it will be <strong>double processed</strong>. This can happen when:</p><ol><li>The Node process running your job processor unexpectedly terminates.</li><li>Your job processor was too CPU-intensive and stalled the Node event loop, and as a result, Bull couldn&#39;t renew the job lock (see <a href="https://github.com/OptimalBits/bull/issues/488" target="_blank" rel="noreferrer">#488</a> for how we might better detect this). You can fix this by breaking your job processor into smaller parts so that no single part can block the Node event loop. Alternatively, you can pass a larger value for the <code>lockDuration</code> setting (with the tradeoff being that it will take longer to recognize a real stalled job).</li></ol><p>As such, you should always listen for the <code>stalled</code> event and log this to your error monitoring system, as this means your jobs are likely getting double-processed.</p><p>As a safeguard so problematic jobs won&#39;t get restarted indefinitely (e.g. if the job processor always crashes its Node process), jobs will be recovered from a stalled state a maximum of <code>maxStalledCount</code> times (default: <code>1</code>).</p>',7)])])}const m=o(r,[["render",n]]);export{h as __pageData,m as default};
